#include <iostream>
using namespace std;

// function to search element in array
int binarySearch(int arr[], int size, int element) {
    int low = 0, high = size - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;

        if (arr[mid] == element) {
            return mid;
        } else if (arr[mid] < element) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return -1; // element not found
}

int main() {
    int arr[100], size, element;

    // input array elements
    cout << "Enter array size: ";
    cin >> size;

    cout << "Enter array elements (sorted): " << endl;
    for (int I = 0; I < size; i++) {
        cin >> arr[i];
    }

    // input element to search
    cout << "Enter element to search: ";
    cin >> element;

    // search element in array
    int index = binarySearch(arr, size, element);

    if (index == -1) {
        cout << "Element not found in array." << endl;
    } else {
        cout << "Element found at index " << index << endl;
    }

    return 0;
}
```

Explanation:

- `binarySearch` function implements the binary search algorithm to find the given element in the sorted array. It takes three arguments - `arr` (array to be searched), `size` (size of array), and `element` (element to be searched). It returns the index of the element if found, else -1.
- The main function inputs the array size, array elements, and the element to be searched using standard input (cin).
- It then calls the `binarySearch` function to search for the given element in the sorted array.
- If the element is found in the array, the program outputs the index of the element. Otherwise, it outputs that the element is not found in the array.

